import React, { useState, useEffect, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, X, Phone, Sparkles, ChevronDown } from "lucide-react";
import { BRAND } from "../types";

const navLinks = [
  { label: "Home", href: "#top" },
  { label: "About", href: "#about" },
  { label: "Reviews", href: "#reviews" },
  { label: "Contact", href: "#contact" },
];

const collections = [
  { label: "Premium Fabrics", image: "https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=100&h=100&fit=crop" },
  { label: "Printed Fabrics", image: "https://images.unsplash.com/photo-1529694157872-4e0c0f6b7d3?w=100&h=100&fit=crop" },
  { label: "Chair Covers", image: "https://images.unsplash.com/photo-1519167758481-83f550bb49b3?w=100&h=100&fit=crop" },
  { label: "Table Covers", image: "https://images.unsplash.com/photo-1530103862676-de8c9debad1d?w=100&h=100&fit=crop" },
  { label: "Pillow & Cushion Covers", image: "https://images.unsplash.com/photo-1584100936595-c0654b55a2e2?w=100&h=100&fit=crop" },
  { label: "Curtains", image: "https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=100&h=100&fit=crop" },
  { label: "Ceilings", image: "https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?w=100&h=100&fit=crop" },
  { label: "Decor Accessories", image: "https://images.unsplash.com/photo-1529636798458-92182e662485?w=100&h=100&fit=crop" },
  { label: "Props", image: "https://images.unsplash.com/photo-1469371670807-013ccf25f16a?w=100&h=100&fit=crop" },
  { label: "Console Tables", image: "https://images.unsplash.com/photo-1555041469-a586c61ea9bc?w=100&h=100&fit=crop" },
  { label: "Chandeliers", image: "https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=100&h=100&fit=crop" },
  { label: "Home Decor", image: "https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?w=100&h=100&fit=crop" },
  { label: "Artificial Flowers", image: "https://images.unsplash.com/photo-1519225421980-715cb0215aed?w=100&h=100&fit=crop" },
];

export default function Navbar({ onOpenQuote }: { onOpenQuote: () => void }) {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);
  const [collectionsOpen, setCollectionsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener("scroll", handleScroll, { passive: true });
    handleScroll();
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setCollectionsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const scrollToSection = (href: string) => {
    document.querySelector(href)?.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <>
      {/* Glassy Navbar - Centered */}
      <motion.header
        className="fixed inset-x-4 top-6 z-50 flex justify-center"
        initial={{ y: -100, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ duration: 0.6, ease: "easeOut" }}
      >
        <motion.div
          className={`w-full max-w-4xl rounded-full px-6 py-3 transition-all duration-500 ${
            scrolled
              ? "bg-white/30 backdrop-blur-3xl shadow-xl shadow-black/5 border border-white/30"
              : "bg-black/20 backdrop-blur-3xl border border-white/10"
          }`}
          layout
        >
          <div className="flex items-center justify-between">
            {/* Logo */}
            <motion.a
              href="#top"
              className="flex items-center"
              whileHover={{ scale: 1.02 }}
              onClick={(e) => { e.preventDefault(); scrollToSection("#top"); }}
            >
              <span className="text-xl font-bold tracking-wider bg-gradient-to-r from-amber-300 via-amber-400 to-amber-500 bg-clip-text text-transparent">
                D SAJAWAT
              </span>
            </motion.a>

            {/* Desktop Navigation */}
            <nav className="hidden lg:flex items-center gap-8">
              {navLinks.map((link, i) => (
                <motion.a
                  key={link.href}
                  href={link.href}
                  className={`text-sm font-medium transition-colors relative group ${
                    scrolled ? "text-gray-700 hover:text-amber-500" : "text-white/90 hover:text-white"
                  }`}
                  initial={{ opacity: 0, y: -20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: i * 0.1 }}
                  onClick={(e) => { e.preventDefault(); scrollToSection(link.href); }}
                >
                  {link.label}
                  <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-amber-400 transition-all group-hover:w-full" />
                </motion.a>
              ))}

              {/* Collections Dropdown with Images */}
              <div ref={dropdownRef} className="relative">
                <motion.button
                  className={`text-sm font-medium transition-colors flex items-center gap-1 group ${
                    scrolled ? "text-gray-700 hover:text-amber-500" : "text-white/90 hover:text-white"
                  }`}
                  initial={{ opacity: 0, y: -20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.4 }}
                  onClick={() => setCollectionsOpen(!collectionsOpen)}
                >
                  Collections
                  <motion.div
                    animate={{ rotate: collectionsOpen ? 180 : 0 }}
                    transition={{ duration: 0.2 }}
                  >
                    <ChevronDown size={16} className={`transition-colors ${scrolled ? "text-gray-700 group-hover:text-amber-500" : "text-white/90 group-hover:text-white"}`} />
                  </motion.div>
                  <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-amber-400 transition-all group-hover:w-full" />
                </motion.button>

                {/* Glassy Dropdown with Scrollable Grid */}
                <AnimatePresence>
                  {collectionsOpen && (
                    <motion.div
                      initial={{ opacity: 0, y: 10, scale: 0.95 }}
                      animate={{ opacity: 1, y: 0, scale: 1 }}
                      exit={{ opacity: 0, y: 10, scale: 0.95 }}
                      transition={{ duration: 0.2 }}
                      className="absolute top-full left-1/2 -translate-x-1/2 mt-3 w-96 bg-white/95 backdrop-blur-2xl rounded-3xl shadow-2xl overflow-hidden border border-white/50"
                    >
                      {/* Header */}
                      <div className="px-5 py-3 border-b border-gray-100">
                        <h3 className="text-sm font-semibold text-gray-800">Browse Categories</h3>
                      </div>
                      {/* Scrollable Grid */}
                      <div className="max-h-80 overflow-y-auto scrollbar-thin scrollbar-thumb-amber-200 scrollbar-track-transparent">
                        <div className="grid grid-cols-3 gap-2 p-3">
                          {collections.map((item, i) => (
                            <motion.a
                              key={item.label}
                              href="#collections"
                              className="group flex flex-col items-center text-center p-3 rounded-2xl hover:bg-amber-50 transition-all"
                              initial={{ opacity: 0, scale: 0.8 }}
                              animate={{ opacity: 1, scale: 1 }}
                              transition={{ delay: i * 0.03 }}
                              onClick={(e) => {
                                e.preventDefault();
                                scrollToSection("#collections");
                                setCollectionsOpen(false);
                              }}
                            >
                              <div className="w-16 h-16 rounded-xl overflow-hidden mb-2 shadow-md group-hover:shadow-lg group-hover:scale-105 transition-all">
                                <img
                                  src={item.image}
                                  alt={item.label}
                                  className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-300"
                                  loading="lazy"
                                />
                              </div>
                              <span className="text-xs font-medium text-gray-700 group-hover:text-amber-600 transition-colors leading-tight">
                                {item.label}
                              </span>
                            </motion.a>
                          ))}
                        </div>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            </nav>

            {/* Desktop CTA */}
            <div className="hidden lg:flex items-center gap-4">
              <motion.a
                href={`tel:${BRAND.phones[0]}`}
                className={`flex items-center gap-2 text-sm font-medium ${scrolled ? "text-amber-500" : "text-white"}`}
                whileHover={{ scale: 1.05 }}
              >
                <Phone size={16} />
                <span>Call Now</span>
              </motion.a>
              <motion.button
                onClick={onOpenQuote}
                className="px-5 py-2 bg-gradient-to-r from-amber-400 to-amber-500 text-white font-semibold text-sm rounded-full flex items-center gap-2 shadow-lg shadow-amber-500/30 hover:shadow-amber-500/50 transition-shadow"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.98 }}
              >
                <Sparkles size={16} />
                <span>Get Quote</span>
              </motion.button>
            </div>

            {/* Mobile Menu Button */}
            <motion.button
              className={`lg:hidden p-2 rounded-full ${scrolled ? "bg-gray-100 text-gray-800" : "bg-white/20 text-white"}`}
              onClick={() => setOpen(!open)}
              whileTap={{ scale: 0.95 }}
            >
              {open ? <X size={20} /> : <Menu size={20} />}
            </motion.button>
          </div>
        </motion.div>
      </motion.header>

      {/* Mobile Menu */}
      <AnimatePresence>
        {open && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden"
              onClick={() => setOpen(false)}
            />
            <motion.div
              initial={{ x: "100%" }}
              animate={{ x: 0 }}
              exit={{ x: "100%" }}
              transition={{ type: "spring", damping: 25, stiffness: 200 }}
              className="fixed top-0 right-0 bottom-0 w-[320px] max-w-[85vw] z-50 bg-white/95 backdrop-blur-2xl shadow-2xl overflow-y-auto"
              style={{ borderRadius: "24px 0 0 24px" }}
            >
              <div className="flex flex-col h-full p-8">
                <div className="flex justify-end mb-8">
                  <motion.button onClick={() => setOpen(false)} className="p-2 rounded-full bg-gray-100" whileTap={{ scale: 0.95 }}>
                    <X size={20} />
                  </motion.button>
                </div>

                <nav className="flex flex-col gap-2 flex-1">
                  {navLinks.map((link, i) => (
                    <motion.a
                      key={link.href}
                      href={link.href}
                      className="text-lg font-semibold text-gray-800 hover:text-amber-500 transition-colors py-2 px-4 rounded-xl hover:bg-amber-50"
                      style={{ fontFamily: "Georgia, serif" }}
                      initial={{ opacity: 0, x: 30 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: i * 0.08 }}
                      onClick={(e) => {
                        e.preventDefault();
                        scrollToSection(link.href);
                        setOpen(false);
                      }}
                    >
                      {link.label}
                    </motion.a>
                  ))}

                  {/* Mobile Collections Accordion with Images */}
                  <div className="mt-4">
                    <motion.button
                      className="flex items-center justify-between w-full text-lg font-semibold text-gray-800 py-2 px-4 rounded-xl hover:bg-amber-50"
                      style={{ fontFamily: "Georgia, serif" }}
                      onClick={() => setCollectionsOpen(!collectionsOpen)}
                      initial={{ opacity: 0, x: 30 }}
                      animate={{ opacity: 1, x: 0 }}
                      transition={{ delay: 0.3 }}
                    >
                      Collections
                      <motion.div animate={{ rotate: collectionsOpen ? 90 : 0 }}>
                        <ChevronDown size={20} className="text-amber-500" />
                      </motion.div>
                    </motion.button>

                    <AnimatePresence>
                      {collectionsOpen && (
                        <motion.div
                          initial={{ height: 0, opacity: 0 }}
                          animate={{ height: "auto", opacity: 1 }}
                          exit={{ height: 0, opacity: 0 }}
                          className="overflow-hidden"
                        >
                          <div className="grid grid-cols-3 gap-2 p-3">
                            {collections.map((item, i) => (
                              <motion.a
                                key={item.label}
                                href="#collections"
                                className="group flex flex-col items-center text-center p-2 rounded-xl hover:bg-amber-50 transition-all"
                                initial={{ opacity: 0, scale: 0.8 }}
                                animate={{ opacity: 1, scale: 1 }}
                                transition={{ delay: i * 0.03 }}
                                onClick={(e) => {
                                  e.preventDefault();
                                  scrollToSection("#collections");
                                  setOpen(false);
                                }}
                              >
                                <div className="w-14 h-14 rounded-lg overflow-hidden mb-1 shadow-sm">
                                  <img
                                    src={item.image}
                                    alt={item.label}
                                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-300"
                                    loading="lazy"
                                  />
                                </div>
                                <span className="text-[10px] font-medium text-gray-700 group-hover:text-amber-600 transition-colors leading-tight">
                                  {item.label}
                                </span>
                              </motion.a>
                            ))}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                </nav>

                <div className="flex flex-col gap-3 pt-6 border-t border-gray-100">
                  <motion.a
                    href={`tel:${BRAND.phones[0]}`}
                    className="flex items-center justify-center gap-3 px-6 py-3 border-2 border-gray-200 rounded-full text-gray-700 font-medium"
                    whileHover={{ borderColor: "#d4af37", color: "#d4af37" }}
                    onClick={() => setOpen(false)}
                  >
                    <Phone size={18} />
                    <span>Call Now</span>
                  </motion.a>
                  <motion.button
                    onClick={() => { setOpen(false); onOpenQuote(); }}
                    className="flex items-center justify-center gap-3 px-6 py-3 bg-gradient-to-r from-amber-400 to-amber-500 rounded-full text-white font-semibold shadow-lg"
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                  >
                    <Sparkles size={18} />
                    <span>Get Quote</span>
                  </motion.button>
                </div>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </>
  );
}
